// invalid inputs

describe('ms(invalid inputs)', function() {
  it('should throw an error, when ms("")', function() {
    expect(function() {
      ms('');
    }).to.throwError();
  });

  it('should throw an error, when ms(undefined)', function() {
    expect(function() {
      ms(undefined);
    }).to.throwError();
  });

  it('should throw an error, when ms(null)', function() {
    expect(function() {
      ms(null);
    }).to.throwError();
  });

  it('should throw an error, when ms([])', function() {
    expect(function() {
      ms([]);
    }).to.throwError();
  });

  it('should throw an error, when ms({})', function() {
    expect(function() {
      ms({});
    }).to.throwError();
  });

  it('should throw an error, when ms(NaN)', function() {
    expect(function() {
      ms(NaN);
    }).to.throwError();
  });
});

const {describe,it}=require('node:test');
var isPromise=require('../src/promise.cjs');
var assert=require('node:assert/strict').ok;

// This looks similar enough to a promise
// that promises/A+ says we should treat
// it as a promise.
var promise = {then: function () {}};

describe('calling isPromise', function () {
  describe('with a promise', function () {
    it('returns true', function () {
      assert(isPromise(promise));
    });
  });
  describe('with null', function () {
    it('returns false', function () {
      assert(isPromise(null) === false);
    });
  });
  describe('with undefined', function () {
    it('returns false', function () {
      assert(isPromise(undefined) === false);
    });
  });
  describe('with a number', function () {
    it('returns false', function () {
      assert(!isPromise(0));
      assert(!isPromise(-42));
      assert(!isPromise(42));
    });
  });
  describe('with a string', function () {
    it('returns false', function () {
      assert(!isPromise(''));
      assert(!isPromise('then'));
    });
  });
  describe('with a bool', function () {
    it('returns false', function () {
      assert(!isPromise(false));
      assert(!isPromise(true));
    });
  });
  describe('with an object', function () {
    it('returns false', function () {
      assert(!isPromise({}));
      assert(!isPromise({then: true}));
    });
  });
  describe('with an array', function () {
    it('returns false', function () {
      assert(!isPromise([]));
      assert(!isPromise([true]));
    });
  });
});

import nodeTest from 'node:test';
import assert from 'node:assert/strict';
import isPlainObject from '../src/plain.mjs';
import {runInNewContext} from 'node:vm';
const test=(name,fn)=>nodeTest(name,()=>fn({true:value=>assert.strictEqual(value,true),false:value=>assert.strictEqual(value,false)}));

function Foo(x) {
	this.x = x;
}

function ObjectConstructor() {}

ObjectConstructor.prototype.constructor = Object;

test('main', t => {
	t.true(isPlainObject({}));
	t.true(isPlainObject({foo: true}));
	t.true(isPlainObject({constructor: Foo}));
	t.true(isPlainObject({valueOf: 0}));
	t.true(isPlainObject(Object.create(null)));
	t.true(isPlainObject(new Object())); // eslint-disable-line no-new-object
	t.true(isPlainObject(runInNewContext('({})')));
	t.false(isPlainObject(['foo', 'bar']));
	t.false(isPlainObject(new Foo(1)));
	t.false(isPlainObject(Math));
	t.false(isPlainObject(Error));
	t.false(isPlainObject(() => {}));
	t.false(isPlainObject(/./));
	t.false(isPlainObject(null));
	t.false(isPlainObject(undefined));
	t.false(isPlainObject(Number.NaN));
	t.false(isPlainObject(''));
	t.false(isPlainObject(0));
	t.false(isPlainObject(false));
	t.false(isPlainObject(new ObjectConstructor()));
	t.false(isPlainObject(Object.create({})));

	(function () {
		t.false(isPlainObject(arguments)); // eslint-disable-line prefer-rest-params
	})();

	const foo = new Foo();
	foo.constructor = Object;
	t.false(isPlainObject(foo));
});

import nodeTest from 'node:test';
import assert from 'node:assert/strict';
import nativeFs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import Stream from 'node:stream';
import net from 'node:net';
import isStream from '../src/stream.cjs';
const test=(name,fn)=>nodeTest(name,async()=>{const streams=[],directory=nativeFs.mkdtempSync(path.join(os.tmpdir(),'testlore-maintainer-stream-'));let count=0;
const track=stream=>(streams.push(stream),stream);
fs={createReadStream:file=>track(nativeFs.createReadStream(file==='test.js'?fileURLToPath(import.meta.url):file)),createWriteStream:file=>track(nativeFs.createWriteStream(file))};
tempy={file:()=>path.join(directory,String(count++))};
try{fn({true:value=>assert.strictEqual(value,true),false:value=>assert.strictEqual(value,false)});}finally{await Promise.all(streams.map(stream=>new Promise(resolve=>{stream.once('close',resolve);stream.destroy();})));nativeFs.rmSync(directory,{recursive:true,force:true});}});
let fs,tempy;

test('isStream()', t => {
	t.true(isStream(new Stream.Stream()));
	t.true(isStream(new Stream.Readable()));
	t.true(isStream(new Stream.Writable()));
	t.true(isStream(new Stream.Duplex()));
	t.true(isStream(new Stream.Transform()));
	t.true(isStream(new Stream.PassThrough()));
	t.true(isStream(fs.createReadStream('test.js')));
	t.true(isStream(fs.createWriteStream(tempy.file())));
	t.true(isStream(new net.Socket()));
	t.false(isStream({}));
	t.false(isStream(null));
	t.false(isStream(undefined));
	t.false(isStream(''));
});

test('isStream.writable()', t => {
	t.true(isStream.writable(new Stream.Writable()));
	t.true(isStream.writable(new Stream.Duplex()));
	t.true(isStream.writable(new Stream.Transform()));
	t.true(isStream.writable(new Stream.PassThrough()));
	t.true(isStream.writable(fs.createWriteStream(tempy.file())));
	t.true(isStream.writable(new net.Socket()));
	t.false(isStream.writable(new Stream.Stream()));
	t.false(isStream.writable(new Stream.Readable()));
	t.false(isStream.writable(fs.createReadStream('test.js')));
});

test('isStream.readable()', t => {
	t.true(isStream.readable(new Stream.Readable()));
	t.true(isStream.readable(new Stream.Duplex()));
	t.true(isStream.readable(new Stream.Transform()));
	t.true(isStream.readable(new Stream.PassThrough()));
	t.true(isStream.readable(fs.createReadStream('test.js')));
	t.true(isStream.readable(new net.Socket()));
	t.false(isStream.readable(new Stream.Stream()));
	t.false(isStream.readable(new Stream.Writable()));
	t.false(isStream.readable(fs.createWriteStream(tempy.file())));
});

test('isStream.duplex()', t => {
	t.true(isStream.duplex(new Stream.Duplex()));
	t.true(isStream.duplex(new Stream.Transform()));
	t.true(isStream.duplex(new Stream.PassThrough()));
	t.false(isStream.duplex(new Stream.Stream()));
	t.false(isStream.duplex(new Stream.Readable()));
	t.false(isStream.duplex(new Stream.Writable()));
	t.false(isStream.duplex(fs.createReadStream('test.js')));
	t.false(isStream.duplex(fs.createWriteStream(tempy.file())));
});

test('isStream.transform()', t => {
	t.true(isStream.transform(new Stream.Transform()));
	t.true(isStream.transform(new Stream.PassThrough()));
	t.false(isStream.transform(new Stream.Duplex()));
	t.false(isStream.transform(new Stream.Stream()));
	t.false(isStream.transform(new Stream.Readable()));
	t.false(isStream.transform(new Stream.Writable()));
	t.false(isStream.transform(fs.createReadStream('test.js')));
	t.false(isStream.transform(fs.createWriteStream(tempy.file())));
});
